package com.fullstack.exp231.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date;
@Service public class JwtService { private final SecretKey key=Keys.hmacShaKeyFor("FullStackII-Exp231-JWT-Secret-Key-2026-LongEnough".getBytes(StandardCharsets.UTF_8)); public String generate(String u,String r){return Jwts.builder().subject(u).claim("role",r).issuedAt(new Date()).expiration(new Date(System.currentTimeMillis()+3600000)).signWith(key).compact();} public Claims claims(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload();} public boolean valid(String t){try{claims(t);return true;}catch(Exception e){return false;}} }
